SEMUA_KONEKSI = {
    **KONEKSI_KABUPATEN,
    "PUSAT SUMUT": DB_PUSAT
}

def uji_koneksi(nama, connection_string):
    conn = psycopg2.connect(connection_string, sslmode="require")
    try:
        with conn.cursor() as cur:
            cur.execute("SELECT current_database(), current_user;")
            hasil = cur.fetchone()
        print(f"BERHASIL - {nama}: database={hasil[0]}, user={hasil[1]}")
    finally:
        conn.close()

for nama, connection_string in SEMUA_KONEKSI.items():
    uji_koneksi(nama, connection_string)

